 const whole=Math.floor(n/d),r=n%d,digit=Math.floor(r*10/d),rem=r*10%d;
 const ss=[N('Сколько целых при делении '+n+' на '+d+'?',whole,'Выделите целую часть до запятой.','Целая часть '+whole+', остаток '+r+'.'),N('Первая цифра после запятой: '+r+' × 10 разделить на '+d+'.',digit,'Увеличьте остаток в десять раз.','Цифра '+digit+', новый остаток '+rem+'. Повторившийся остаток запускает период.'),S('Запишите '+n+'/'+d+' как бесконечную периодическую десятичную дробь.',{type:'period',value:n/d},periodic(n,d),'Период поместите в скобки. Конечную дробь можно продолжить нулями: …(0).','Периодическая запись проверена по её точному дробному значению.',{final:true})];
 if(round)for(let p=1;p<=3;p++){const v=Math.round(n/d*10**p)/10**p;ss.push(N('Округлите исходную дробь до '+['','десятых','сотых','тысячных'][p]+'.',v,'Смотрите на следующую цифру. Каждый раз округляйте исходное число, не предыдущий результат.','Правильное округление: '+v.toFixed(p).replace('.',',')+'.'));ss.at(-1).final=true;}
 return part(label,n+'/'+d,ss,'v5f-decimal-fraction');
