function orderPart(label,title,display,correct,hint){return part(label,title,[Q('В порядке возрастания числа идут…',options(['слева направо по прямой','справа налево по прямой']),['слева направо по прямой'],'На прямой большее число правее.','Для убывания направление обратное.'),S(title,{type:'order',answer:correct},correct,hint,'Все числа стоят в требуемом порядке.',{options:options(display)})],'m9f-negative-compare');}
