function comparePart(label,a,b,sign,explain){const both=a.startsWith('−')&&b.startsWith('−'),different=a.startsWith('−')!==b.startsWith('−');const strategy=both?'Сравнить модули и обратить знак':different?'Сначала учесть разные знаки':'Привести к общей форме записи';return part(label,a+' и '+b,[Q('Какой первый приём подходит для сравнения '+a+' и '+b+'?',options(['Сравнить модули и обратить знак','Сначала учесть разные знаки','Привести к общей форме записи']),[strategy],both?'Оба числа отрицательны.':different?'Одно число отрицательное, другое положительное.':'Для положительных чисел удобно сравнить десятичные записи или дроби с общим знаменателем.',strategy+'.'),Q('Выберите знак: '+a+' … '+b,options(['<','=','>']),[sign],explain,explain)],'m9f-negative-compare');}
