function errorPart(label,x,p,roundRequired){const rounded=Math.round(x*10**p)/10**p,s=N('Округлите '+fmtDecimal(x)+' до '+({1:'десятых',2:'сотых',0:'единиц','-1':'десятков'}[p])+'.',rounded,'Следующая цифра 5 или больше увеличивает сохраняемый разряд.','Округлённое значение '+fmtDecimal(rounded)+'.');if(roundRequired)s.final=true;return part(label,fmtDecimal(x),[s,N('Найдите абсолютную погрешность этого приближения.',Math.abs(x-rounded),'Погрешность — модуль разности точного и приближённого значений. Она неотрицательна.','Это расстояние между точным и округлённым числами.')],'m9f-absolute-error');}
