function openResearch(n,title,labels){const p=part('',title,[
 pick('Что нужно записать, чтобы другой человек мог проверить пример?',['Объект или процесс, значение, единицу и источник','Только большое или маленькое число'],'Объект или процесс, значение, единицу и источник','Число без единицы не задаёт величину.','Источник должен позволять найти именно приведённую оценку.'),
 form('Приведите два собственных примера. Укажите название справочника и страницу либо адрес источника. Никакие адреса автоматически не открываются.','research',labels.flatMap((label,i)=>[F('item'+i,label+' — что сравниваем','text'),F('value'+i,'Числовое значение'),F('unit'+i,'Единица измерения','text'),F('source'+i,'Источник и место в нём','text')]),{item0:'Классная комната',value0:'8',unit0:'м',source0:'Собственное измерение рулеткой',item1:'Толщина листа',value1:'.0001',unit1:'м',source1:'Пример оценки; сверить с измерением'},'Приведите измеримые примеры. У очень больших и малых величин используйте степени десяти.','Запись сохранена для обсуждения. Программа проверила заполнение полей и положительность значений; достоверность источника и уместность примеров оцениваете вы с учителем.')],'m9f-standard-form');p.manual=true;add(n,title,[p]);}
